-- Replace is the complete cart union: attachment-distinct offers must retain
-- independent identities; caller-provided accepted flags still pass policy.
UPDATE public.products SET price=15,brand='Apple',name='Fixture',inventory_tracking_policy='off',stock=20,stock_quantity=20 WHERE id='44444444-4444-4444-8444-444444444444';
INSERT INTO public.commerce_carts(id,merchant_id,expires_at) VALUES('aaaaaaaa-4000-4000-8000-000000000001','11111111-1111-4111-8111-111111111111',now()+interval '7 days');
INSERT INTO public.commerce_cart_grants(id,merchant_id,cart_id,principal_id,expires_at) VALUES('bbbbbbbb-4000-4000-8000-000000000001','11111111-1111-4111-8111-111111111111','aaaaaaaa-4000-4000-8000-000000000001','replace-attachment-device',now()+interval '7 days');
SET request.jwt.claims='{"role":"commerce_cart_shopper","exp":9999999999,"cart_scope":"session","cart_merchant_id":"11111111-1111-4111-8111-111111111111","cart_principal_id":"replace-attachment-device","cart_id":"aaaaaaaa-4000-4000-8000-000000000001","cart_grant_id":"bbbbbbbb-4000-4000-8000-000000000001"}';
DO $$ DECLARE command jsonb:='{"type":"replace","lines":[{"item":{"productId":"44444444-4444-4444-8444-444444444444"},"quantity":2,"negotiatedUnitPriceMinor":1470,"negotiationStatus":"accepted"},{"item":{"productId":"44444444-4444-4444-8444-444444444444"},"quantity":3,"negotiatedUnitPriceMinor":1480,"negotiationStatus":"accepted"},{"item":{"productId":"44444444-4444-4444-8444-444444444444"},"quantity":1,"negotiatedUnitPriceMinor":1480,"negotiationStatus":"pending"}]}'; r jsonb; cart uuid:='aaaaaaaa-4000-4000-8000-000000000001'; expiry timestamptz; BEGIN
 r:=public.commerce_cart_mutate(cart,'replace-attachment-siblings',1,command);
 IF r->>'ok' IS DISTINCT FROM 'true' OR (SELECT count(*) FROM public.commerce_cart_lines WHERE cart_id=cart) IS DISTINCT FROM 3::bigint THEN RAISE EXCEPTION 'replace collapsed legal negotiation siblings %',r; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.commerce_cart_lines WHERE cart_id=cart AND negotiated_unit_price_minor=1470 AND negotiation_status='accepted' AND quantity=2) OR NOT EXISTS(SELECT 1 FROM public.commerce_cart_lines WHERE cart_id=cart AND negotiated_unit_price_minor=1480 AND negotiation_status='accepted' AND quantity=3) OR NOT EXISTS(SELECT 1 FROM public.commerce_cart_lines WHERE cart_id=cart AND negotiated_unit_price_minor=1480 AND negotiation_status='pending' AND quantity=1) THEN RAISE EXCEPTION 'replace mixed negotiation amounts/status/quantities'; END IF;
 SELECT expires_at INTO STRICT expiry FROM public.commerce_carts WHERE id=cart;
 r:=public.commerce_cart_mutate(cart,'replace-attachment-noop',2,command);
 IF r->>'ok' IS DISTINCT FROM 'true' OR (r->>'currentVersion')::integer IS DISTINCT FROM 2 OR (SELECT expires_at FROM public.commerce_carts WHERE id=cart) IS DISTINCT FROM expiry THEN RAISE EXCEPTION 'identical attachment union changed cart version/expiry %',r; END IF;
 r:=public.commerce_cart_mutate(cart,'replace-attachment-siblings',1,command);
 IF r->>'replayed' IS DISTINCT FROM 'true' OR (r->>'currentVersion')::integer IS DISTINCT FROM 2 OR (SELECT count(*) FROM public.commerce_cart_events WHERE cart_id=cart) IS DISTINCT FROM 1::bigint THEN RAISE EXCEPTION 'attachment replacement retry changed version/outbox %',r; END IF;
 -- Selecting a new negotiation replaces the old sibling identities. A deep
 -- self-proposal cannot smuggle accepted state through the full replace.
 r:=public.commerce_cart_mutate(cart,'replace-attachment-selected-negotiation',2,'{"type":"replace","lines":[{"item":{"productId":"44444444-4444-4444-8444-444444444444"},"quantity":1,"negotiatedUnitPriceMinor":1000,"negotiationStatus":"accepted"}]}');
 IF r->>'ok' IS DISTINCT FROM 'true' OR (SELECT count(*) FROM public.commerce_cart_lines WHERE cart_id=cart) IS DISTINCT FROM 1::bigint OR NOT EXISTS(SELECT 1 FROM public.commerce_cart_lines WHERE cart_id=cart AND negotiated_unit_price_minor=1000 AND negotiation_status='pending') THEN RAISE EXCEPTION 'selected negotiation was lost or caller accepted flag trusted %',r; END IF;
 r:=public.commerce_cart_mutate(cart,'replace-attachment-selected-accepted',3,'{"type":"replace","lines":[{"item":{"productId":"44444444-4444-4444-8444-444444444444"},"quantity":1,"negotiatedUnitPriceMinor":1485,"negotiationStatus":"accepted"}]}');
 IF r->>'ok' IS DISTINCT FROM 'true' OR NOT EXISTS(SELECT 1 FROM public.commerce_cart_lines WHERE cart_id=cart AND negotiated_unit_price_minor=1485 AND negotiation_status='accepted') THEN RAISE EXCEPTION 'changed negotiated amount/status did not replace previous offer %',r; END IF;
 -- Quantity and assurance are not identity: ordinary duplicates still merge.
 r:=public.commerce_cart_mutate(cart,'replace-attachment-ordinary-duplicates',4,'{"type":"replace","lines":[{"item":{"productId":"44444444-4444-4444-8444-444444444444"},"quantity":2},{"item":{"productId":"44444444-4444-4444-8444-444444444444"},"quantity":3,"hasAssurance":true}]}');
 IF r->>'ok' IS DISTINCT FROM 'true' OR (SELECT count(*) FROM public.commerce_cart_lines WHERE cart_id=cart) IS DISTINCT FROM 1::bigint OR NOT EXISTS(SELECT 1 FROM public.commerce_cart_lines WHERE cart_id=cart AND quantity=5 AND has_assurance AND negotiated_unit_price_minor IS NULL) THEN RAISE EXCEPTION 'ordinary duplicate/assurance union regressed %',r; END IF;
 r:=public.commerce_cart_mutate(cart,'replace-attachment-ordinary-cap',5,'{"type":"replace","lines":[{"item":{"productId":"44444444-4444-4444-8444-444444444444"},"quantity":6},{"item":{"productId":"44444444-4444-4444-8444-444444444444"},"quantity":6}]}');
 IF r->>'ok' IS DISTINCT FROM 'false' OR r->>'code' IS DISTINCT FROM 'invalid_item' OR (SELECT quantity FROM public.commerce_cart_lines WHERE cart_id=cart) IS DISTINCT FROM 5 THEN RAISE EXCEPTION 'ordinary duplicate cap partially committed %',r; END IF;
 r:=public.commerce_cart_mutate(cart,'replace-attachment-selected-voucher',5,jsonb_build_object('type','replace','lines',jsonb_build_array(jsonb_build_object('item',jsonb_build_object('productId','44444444-4444-4444-8444-444444444444'),'quantity',7,'voucherToken',repeat('v',400),'voucherAwardId','cccccccc-4000-4000-8000-000000000001'))));
 IF r->>'ok' IS DISTINCT FROM 'true' OR (SELECT count(*) FROM public.commerce_cart_lines WHERE cart_id=cart) IS DISTINCT FROM 1::bigint OR NOT EXISTS(SELECT 1 FROM public.commerce_cart_lines WHERE cart_id=cart AND quantity=1 AND voucher_token=repeat('v',400) AND voucher_award_id='cccccccc-4000-4000-8000-000000000001' AND negotiated_unit_price_minor IS NULL) THEN RAISE EXCEPTION 'selected voucher did not replace lone ordinary offer %',r; END IF;
END $$;
